import sys

def main():
    data = sys.stdin.read().split()
    R, C = int(data[0]), int(data[1])
    g = data[2:2 + R]
    P = 'EFWA'
    stage = {'E': 0, 'F': 1, 'W': 2, 'A': 3}
    N = 2 * R * C + 2
    S, T = N - 2, N - 1
    to, cap = [], []
    adj = [[] for _ in range(N)]
    def add(u, v):
        adj[u].append(len(to)); to.append(v); cap.append(1)
        adj[v].append(len(to)); to.append(u); cap.append(0)
    for i in range(R):
        for j in range(C):
            c = i * C + j
            s = stage[g[i][j]]
            add(2 * c, 2 * c + 1)
            if s == 0:
                add(S, 2 * c)
            if s == 3:
                add(2 * c + 1, T)
            else:
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + di, j + dj
                    if 0 <= a < R and 0 <= b < C and stage[g[a][b]] == s + 1:
                        add(2 * c + 1, 2 * (a * C + b))
    flow = 0
    while True:
        level = [-1] * N
        level[S] = 0
        q = [S]
        for u in q:
            for e in adj[u]:
                if cap[e] > 0 and level[to[e]] < 0:
                    level[to[e]] = level[u] + 1
                    q.append(to[e])
        if level[T] < 0:
            break
        it = [0] * N
        path = []
        u = S
        while True:
            if u == T:
                for e in path:
                    cap[e] -= 1
                    cap[e ^ 1] += 1
                flow += 1
                path = []
                u = S
                continue
            adv = False
            au = adj[u]
            while it[u] < len(au):
                e = au[it[u]]
                v = to[e]
                if cap[e] > 0 and level[v] == level[u] + 1:
                    path.append(e)
                    u = v
                    adv = True
                    break
                it[u] += 1
            if not adv:
                if u == S:
                    break
                level[u] = -1
                e = path.pop()
                u = to[e ^ 1]
                it[u] += 1
    print(flow)

main()

