P = 'EFWA'
paths = []

def dfs(i, j, k, cur):
    if g[i][j] != P[k]:
        return
    cur = cur + [(i, j)]
    if k == 3:
        paths.append(frozenset(cur))
        return
    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        a, b = i + di, j + dj
        if 0 <= a < R and 0 <= b < C:
            dfs(a, b, k + 1, cur)

for i in range(R):
    for j in range(C):
        dfs(i, j, 0, [])
paths = list(set(paths))
best = 0

def go(s, used, cnt):
    global best
    if cnt > best:
        best = cnt
    for x in range(s, len(paths)):
        if not (paths[x] & used):
            go(x + 1, used | paths[x], cnt + 1)

go(0, frozenset(), 0)
print(best)

